import React from 'react';
import { Typography, Divider } from 'antd';
import airlines from '../data/airlines_full';
import { sources, getSourceByCodename } from '../data/sources';

const { Text, Title } = Typography;

const FlightTooltip = ({ 
  flights,
  classCode,
  isDirect,
  closeTooltip
}) => {
  // Get airline name based on code
  const getAirlineName = (codename) => {
    const airline = airlines.find(a => a.iata === codename);
    return airline ? `${codename} - ${airline.name}` : codename;
  };

  // Create flights rows
  const createFlightRow = (flight) => {
    const { 
      airlines: flightAirlines, 
      miles, 
      points, 
      direct, 
      source,
      rawData 
    } = flight;

    // Get points/miles
    const milesCost = miles || points || 
      (rawData && rawData[`${classCode}MileageCost`]) || 
      'N/A';

    // Get taxes
    const taxes = rawData && rawData[`${classCode}TotalTaxes`] || 'N/A';
    const currency = rawData && rawData.TaxesCurrency || '';

    // Format airlines
    const airlinesArray = Array.isArray(flightAirlines) 
      ? flightAirlines 
      : (flightAirlines || '').split(',').map(a => a.trim()).filter(Boolean);

    // Get source info
    const sourceInfo = getSourceByCodename(source);
    const sourceName = sourceInfo ? sourceInfo.name : source;

    return (
      <div className="tooltip-flight-row" key={`${source}-${flightAirlines}`}>
        <div className="tooltip-flight-detail">
          <Text strong>Source:</Text> {sourceName}
        </div>
        <div className="tooltip-flight-detail">
          <Text strong>Airlines:</Text> {airlinesArray.map(getAirlineName).join(', ')}
        </div>
        <div className="tooltip-flight-detail">
          <Text strong>Type:</Text> {direct ? 'Direct' : 'Connection'}
        </div>
        <div className="tooltip-flight-detail">
          <Text strong>Cost:</Text> {typeof milesCost === 'number' ? milesCost.toLocaleString() : milesCost} points
        </div>
        {taxes !== 'N/A' && (
          <div className="tooltip-flight-detail">
            <Text strong>Taxes:</Text> {typeof taxes === 'number' ? taxes.toLocaleString() : taxes} {currency}
          </div>
        )}
        <Divider style={{ margin: '8px 0' }} />
      </div>
    );
  };

  // Class name mapping
  const classNames = {
    'Y': 'Economy',
    'W': 'Premium Economy',
    'J': 'Business',
    'F': 'First'
  };

  return (
    <div className="flight-tooltip">
      <div className="tooltip-header">
        <Title level={5}>
          {classNames[classCode] || classCode} Class
          {isDirect ? ' (Direct Flights)' : ''}
        </Title>
        <span className="tooltip-close" onClick={closeTooltip}>×</span>
      </div>

      <div className="tooltip-content">
        {flights.length > 0 ? (
          flights.map(flight => createFlightRow(flight))
        ) : (
          <div className="no-flights">No flights data available</div>
        )}
      </div>
    </div>
  );
};

export default FlightTooltip;
